function chunkedTask(items, processItem) {
  let index = 0;
  function run() {
    const slice = items.slice(index, index + 10);
    slice.forEach(processItem);
    index += 10;
    if (index < items.length) {
      setTimeout(run, 0); // yields to main thread
    }
  }
  run();
