function processArrayAsync(arr, callback) {
  let index = 0;
  function step(deadline) {
    while (index < arr.length && (deadline.timeRemaining() > 0 || deadline.didTimeout)) {
      callback(arr[index]);
      index++;
    }
    if (index < arr.length) {
      requestIdleCallback(step);
    }
  }
  requestIdleCallback(step);
}

